"""Marketing operations and resource work queue."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM marketing operations workspace"], include_in_schema=False)
_HEADERS = {
    "Cache-Control": "no-store",
    "Content-Security-Policy": "default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'",
    "Referrer-Policy": "no-referrer",
    "X-Content-Type-Options": "nosniff",
}
_PAGE = """<!doctype html>
<html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>عملیات و منابع بازاریابی | فانل CRM</title>
<style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px minmax(0,1fr)}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:800;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav:hover,.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top{display:flex;align-items:center;gap:12px;margin-bottom:24px}.top select{min-width:190px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;margin-bottom:20px}.filters{display:flex;gap:8px;align-items:end;flex-wrap:wrap}.filters label,.field{display:grid;gap:6px;font-size:11px;color:#778697}input,select,textarea{font:inherit;color:#33465c;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:140px}button{font:inherit;cursor:pointer}.primary{border:0;background:#126b91;color:white;border-radius:9px;padding:11px 16px;font-weight:700}.secondary{border:1px solid #d8e2ea;background:white;color:#31536c;border-radius:8px;padding:8px 11px}.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408}.label{color:#657487;font-size:12px}.value{font-size:23px;font-weight:800;margin:11px 0 4px}.meta{color:#8290a0;font-size:10px}.layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(280px,.8fr);gap:14px}.section-title{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px;font-size:15px}.queue{display:grid;gap:9px}.task{border:1px solid #e8edf2;border-radius:10px;padding:13px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center}.task strong{font-size:13px}.task p{margin:6px 0 0;color:#728093;font-size:11px;line-height:1.7}.chips{display:flex;gap:5px;flex-wrap:wrap;margin-top:7px}.chip{font-size:10px;background:#eff4f7;color:#526b7e;border-radius:99px;padding:4px 8px}.chip.late{background:#fff0eb;color:#a34e36}.actions{display:flex;gap:6px;flex-wrap:wrap;justify-content:flex-end}.form{display:grid;gap:12px}.form textarea{min-height:75px;resize:vertical}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.notice{color:#718092;font-size:11px;line-height:1.8;margin-top:12px}.empty{border:1px dashed #d4dde6;border-radius:9px;padding:20px;color:#7b8998;font-size:12px;text-align:center;line-height:1.8}#status{min-height:20px;color:#718092;font-size:12px;margin:0 0 8px}#status.error{color:#a74137}
@media(max-width:900px){.layout{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:9px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.head{display:block}.filters{margin-top:14px}.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:480px){.main{padding:15px 12px 32px}.top{align-items:stretch;flex-direction:column}.top select{width:100%}.filters{display:grid;grid-template-columns:1fr 1fr}.filters select{min-width:0;width:100%}.task{grid-template-columns:1fr}.actions{justify-content:flex-start}.form-row{grid-template-columns:1fr}}
</style><script src="/assets/crm-operations-workspace.js" defer></script></head>
<body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM">
<a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-customers">مشتریان</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/crm-sales">فروش و درآمد</a><a class="nav active" href="/workspace/crm-operations" aria-current="page">عملیات و منابع</a></nav></aside>
<main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace-id"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="organization-unit"><option value="">ابتدا فضای کاری را انتخاب کنید</option></select></label></div>
<header class="head"><div><h1>عملیات و منابع بازاریابی</h1><p class="sub">صف کارها، موعدهای پیگیری و توزیع ظرفیت اجرایی تیم را در یک نمای عملیاتی مدیریت کنید.</p></div>
<div class="filters"><label class="field">وضعیت<select id="status-filter"><option value="">همهٔ وضعیت‌ها</option><option value="open">باز</option><option value="in_progress">در حال انجام</option><option value="completed">تکمیل‌شده</option><option value="cancelled">لغوشده</option></select></label><label class="field">نمایش<select id="ownership-filter"><option value="all">کل واحد</option><option value="mine">کارهای من</option></select></label><button id="refresh" class="primary" type="button">به‌روزرسانی</button></div></header>
<p id="status" role="status" aria-live="polite"></p><section class="kpis" aria-label="خلاصه منابع"><article class="card"><div class="label">کارهای باز</div><div id="kpi-open" class="value">—</div><div class="meta">در کل واحد انتخاب‌شده</div></article><article class="card"><div class="label">در حال انجام</div><div id="kpi-progress" class="value">—</div><div class="meta">ظرفیت فعال تیم</div></article><article class="card"><div class="label">عقب‌افتاده</div><div id="kpi-overdue" class="value">—</div><div class="meta">کار باز با موعد گذشته</div></article><article class="card"><div class="label">بدون مسئول</div><div id="kpi-unassigned" class="value">—</div><div class="meta">نیازمند تخصیص به عضو تیم</div></article></section>
<div class="layout"><section class="card"><h2 class="section-title">صف عملیات <span id="result-count" class="meta"></span></h2><div id="queue" class="queue"><div class="empty">برای مشاهدهٔ صف، فضای کاری و واحد سازمانی را انتخاب کنید.</div></div><p class="notice">شاخص‌های منابع از کارهای واقعی ثبت‌شده در CRM محاسبه می‌شوند؛ ظرفیت برنامه‌ریزی‌شدهٔ اعضا در این نما به‌عنوان دادهٔ ثبت‌نشده نمایش داده نمی‌شود.</p></section>
<section class="card"><h2 class="section-title">ثبت کار عملیاتی</h2><form id="task-form" class="form"><label class="field">عنوان کار<input id="task-title" maxlength="200" required placeholder="مثلاً پیگیری سرنخ‌های کمپین"></label><label class="field">پروندهٔ مشتری<input id="profile-search" placeholder="جست‌وجوی نام مشتری"></label><label class="field">اتصال به پرونده<select id="profile-id" required><option value="">ابتدا واحد را انتخاب کنید</option></select></label><label class="field">شرح<textarea id="task-description" maxlength="2000" placeholder="جزئیات و اقدام بعدی"></textarea></label><div class="form-row"><label class="field">اولویت<select id="task-priority"><option value="normal">معمولی</option><option value="low">کم</option><option value="high">بالا</option><option value="urgent">فوری</option></select></label><label class="field">موعد<input id="task-due" type="datetime-local"></label></div><button id="save-task" class="primary" type="submit">ثبت کار</button></form><p class="notice">هر کار باید به یک پروندهٔ مشتری متصل باشد. ارجاع به فرصت یا کمپین نیز از API پشتیبانی می‌شود و در گام اتصال سایر میزکارها فعال خواهد شد.</p></section></div></main></div></body></html>"""
_SCRIPT = """(() => {
const $=id=>document.getElementById(id),workspace=$("workspace-id"),unit=$("organization-unit"),statusFilter=$("status-filter"),ownerFilter=$("ownership-filter");
const n=new Intl.NumberFormat("fa-IR"),priority={low:"کم",normal:"معمولی",high:"بالا",urgent:"فوری"},state={open:"باز",in_progress:"در حال انجام",completed:"تکمیل‌شده",cancelled:"لغوشده"};
let tasks=[],profiles=[];
function say(text,error=false){$("status").textContent=text;$("status").classList.toggle("error",error)}
function el(tag,text,cls=""){const x=document.createElement(tag);x.textContent=String(text??"");if(cls)x.className=cls;return x}
async function api(path,options={}){const headers={Accept:"application/json",...(options.headers||{})};if(options.body)headers["Content-Type"]="application/json";if(workspace.value)headers["X-Workspace-ID"]=workspace.value;const res=await fetch(path,{credentials:"same-origin",...options,headers});let data={};try{data=res.status===204?{}:await res.json()}catch(_){}if(!res.ok){const d=typeof data.detail==="string"?data.detail:data.detail?.message;throw Error(d||"درخواست ناموفق بود ("+res.status+").")}return data}
function fillProfiles(search=""){const select=$("profile-id"),q=search.trim().toLocaleLowerCase();select.replaceChildren();const placeholder=el("option",profiles.length?"پروندهٔ مشتری را انتخاب کنید":"مشتری فعالی پیدا نشد");placeholder.value="";select.appendChild(placeholder);profiles.filter(p=>!q||String(p.display_name||"").toLocaleLowerCase().includes(q)).forEach(p=>{const o=el("option",p.display_name);o.value=p.id;select.appendChild(o)})}
async function loadProfiles(){profiles=[];fillProfiles();if(!unit.value)return;const data=await api("/api/v1/crm/profiles?limit=200&organization_unit_id="+encodeURIComponent(unit.value));profiles=data.items||[];fillProfiles($("profile-search").value)}
function render(){const now=Date.now(),active=tasks.filter(t=>["open","in_progress"].includes(t.status));$("kpi-open").textContent=n.format(tasks.filter(t=>t.status==="open").length);$("kpi-progress").textContent=n.format(tasks.filter(t=>t.status==="in_progress").length);$("kpi-overdue").textContent=n.format(active.filter(t=>t.due_at&&Date.parse(t.due_at)<now).length);$("kpi-unassigned").textContent=n.format(active.filter(t=>!t.assigned_membership_id).length);$("result-count").textContent=n.format(tasks.length)+" کار";const host=$("queue");host.replaceChildren();if(!tasks.length){host.appendChild(el("div","در این فیلتر کاری ثبت نشده است.","empty"));return}tasks.forEach(t=>{const row=document.createElement("article");row.className="task";const info=document.createElement("div");info.appendChild(el("strong",t.title));const meta=el("p",(t.description||"بدون شرح")+" · "+(t.due_at?"موعد: "+new Date(t.due_at).toLocaleString("fa-IR"):"بدون موعد"));info.appendChild(meta);const chips=document.createElement("div");chips.className="chips";chips.appendChild(el("span",state[t.status]||t.status,"chip"));chips.appendChild(el("span","اولویت "+(priority[t.priority]||t.priority),"chip"));chips.appendChild(el("span",t.assigned_membership_id?"مسئول دارد":"بدون مسئول","chip"));if(t.due_at&&Date.parse(t.due_at)<now&&["open","in_progress"].includes(t.status))chips.appendChild(el("span","عقب‌افتاده","chip late"));info.appendChild(chips);row.appendChild(info);const actions=document.createElement("div");actions.className="actions";if(t.status==="open"){const b=el("button","شروع کار","secondary");b.type="button";b.addEventListener("click",()=>changeStatus(t,"in_progress"));actions.appendChild(b)}if(["open","in_progress"].includes(t.status)){const b=el("button","تکمیل","primary");b.type="button";b.addEventListener("click",()=>changeStatus(t,"completed"));actions.appendChild(b)}row.appendChild(actions);host.appendChild(row)})}
async function load(){if(!workspace.value||!unit.value){$("queue").replaceChildren(el("div","برای مشاهدهٔ صف، فضای کاری و واحد سازمانی را انتخاب کنید.","empty"));return}say("در حال دریافت صف کار…");try{const params=new URLSearchParams({organization_unit_id:unit.value,limit:"200"});if(statusFilter.value)params.set("status",statusFilter.value);if(ownerFilter.value==="mine")params.set("assigned_to_me","true");tasks=await api("/api/v1/crm/work-items?"+params.toString());render();say("صف عملیات به‌روز شد.")}catch(e){say(e.message,true)}}
async function changeStatus(task,next){try{await api("/api/v1/crm/work-items/"+encodeURIComponent(task.id),{method:"PATCH",body:JSON.stringify({status:next})});say("وضعیت کار به‌روز شد.");await load()}catch(e){say(e.message,true)}}
async function init(){try{const spaces=await api("/api/v1/system/workspaces");workspace.replaceChildren();const ph=el("option","فضای کاری را انتخاب کنید");ph.value="";workspace.appendChild(ph);spaces.forEach(s=>{const o=el("option",s.name);o.value=s.id;workspace.appendChild(o)});const requested=new URLSearchParams(location.search).get("workspace_id");workspace.value=spaces.some(s=>s.id===requested)?requested:(spaces.length===1?spaces[0].id:"");if(workspace.value)await loadUnits();else say("فضای کاری را انتخاب کنید.")}catch(e){say(e.message,true)}}
async function loadUnits(){unit.replaceChildren();const ph=el("option","واحد سازمانی را انتخاب کنید");ph.value="";unit.appendChild(ph);if(!workspace.value)return;const rows=await api("/api/v1/system/opportunity-organization-units");rows.forEach(x=>{const o=el("option",x.name);o.value=x.id;unit.appendChild(o)});if(rows.length===1)unit.value=rows[0].id;if(unit.value){await loadProfiles();await load()}else say("واحد سازمانی را انتخاب کنید.")}
workspace.addEventListener("change",async()=>{unit.value="";tasks=[];profiles=[];try{await loadUnits()}catch(e){say(e.message,true)}});unit.addEventListener("change",async()=>{try{await loadProfiles();await load()}catch(e){say(e.message,true)}});statusFilter.addEventListener("change",load);ownerFilter.addEventListener("change",load);$("refresh").addEventListener("click",load);$("profile-search").addEventListener("input",()=>fillProfiles($("profile-search").value));
$("task-form").addEventListener("submit",async ev=>{ev.preventDefault();if(!unit.value||!$("profile-id").value){say("فضا، واحد و پروندهٔ مشتری را انتخاب کنید.",true);return}const due=$("task-due").value;const payload={organization_unit_id:unit.value,profile_id:$("profile-id").value,title:$("task-title").value,description:$("task-description").value||null,priority:$("task-priority").value,due_at:due?new Date(due).toISOString():null};$("save-task").disabled=true;try{await api("/api/v1/crm/work-items",{method:"POST",body:JSON.stringify(payload)});$("task-form").reset();fillProfiles();say("کار عملیاتی ثبت شد.");await load()}catch(e){say(e.message,true)}finally{$("save-task").disabled=false}});
init();
})();"""

@router.get("/workspace/crm-operations", response_class=HTMLResponse)
async def crm_operations_workspace_page() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-operations-workspace.js")
async def crm_operations_workspace_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff"})
